const fakeEmail = _faker.faker.internet.email();
const fakeFirstName = _faker.faker.person.firstName();
const fakeLastName = _faker.faker.person.lastName();
const fakePassword = _faker.faker.internet.password();
// Étape 1 : créer un utilisateur pour obtenir un token
cy.request({
  method: "POST",
  url: apiUrl + "/register",
  body: {
    email: fakeEmail,
    firstname: fakeFirstName,
    lastname: fakeLastName,
    plainPassword: {
      first: fakePassword,
      second: fakePassword
    }
  }
}).then(resRegister => {
  expect(resRegister.status).to.eq(200);
  // Étape 2 : login pour obtenir un token valide
  cy.request("POST", apiUrl + "/login", {
    username: fakeEmail,
    password: fakePassword
  }).then(resLogin => {
    expect(resLogin.status).to.eq(200);
    const token = resLogin.body.token;
    // Étape 3 : test GET /orders
    cy.request({
      method: "GET",
      url: apiUrl + "/orders",
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: "application/json"
      },
      failOnStatusCode: false
    }).then(response => {
      expect(response.status).to.eq(404);
      if (typeof response.body === "string") {
        expect(response.body).to.include("Aucune commande en cours");
      }
    });
  });
});
